import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// The aliases GitHub Linguist lists for languages, alias -> name: `csharp` -> C#, `cpp` -> C++.
// Generated by scripts/build-language-aliases.js.
const { aliases: LANGUAGE_ALIASES } = JSON.parse(fs.readFileSync(path.join(__dirname, '../../assets/languageAliases.json'), 'utf8'));

/**
 * A language's default alias, as GitHub Linguist derives it: the name in lower case, with hyphens
 * for spaces. `HTML` -> `html`, `Jupyter Notebook` -> `jupyter-notebook`.
 */
const defaultAlias = (name) => name.toLowerCase().replace(/\s/g, '-');

// The legend has two columns of 10 entries.
const MAX_LANGUAGES = 20;

// Names that are too long for the legend, shown shorter.
const SHORT_NAMES = { 'Jupyter Notebook': 'Jupyter' };

/**
 * Calculates the k-metric and percentage for each language, including color.
 *
 * Only the top 20 languages (by k-metric) are kept, and percentages are taken over those,
 * so the language ring always adds up to 100% with no gap. Ignored languages are left out
 * before that, so the next language moves up and the rest share their part.
 *
 * @param {object} languages An object where keys are language names and values are objects containing size, count, and color.
 * @param {object} [options]
 * @param {Set<string>} [options.ignore] Default aliases of the languages to leave out (see parseIgnoredLanguages).
 * @returns {array} An array of objects, each containing language name, percentage and color, sorted by percentage.
 */
export function calculateLanguagePercentage(languages, { ignore = new Set() } = {}) {
  // Step 1: Calculate k-metric for each language and keep the top ones
  const topLanguages = Object.entries(languages)
    .filter(([name]) => !ignore.has(defaultAlias(name)))
    .map(([name, { size, count, color }]) => ({ name, k: Math.sqrt(size * count), color }))
    .filter(({ k }) => k > 0)
    .sort((a, b) => b.k - a.k)
    .slice(0, MAX_LANGUAGES);

  // Step 2: Calculate total k-metric of the languages that will be shown
  const totalK = topLanguages.reduce((sum, { k }) => sum + k, 0);
  if (totalK === 0) return [];

  // Step 3: Calculate percentage based on k-metric
  return topLanguages.map(({ name, k, color }) => ({
    name: SHORT_NAMES[name] ?? name,
    percentage: (k / totalK) * 100,
    color,
  }));
}

/**
 * Reads the languages to leave out of the card from the `ignore_languages` query parameter, a
 * comma-separated list such as `ignore_languages=html,css,jupyter-notebook,csharp`. The parameter
 * may also be given several times.
 *
 * Languages are named only the way GitHub search names them (`language:csharp`), by GitHub
 * Linguist's aliases: a language's default alias (see defaultAlias) or one of the aliases Linguist
 * lists for it, such as `csharp` for C# and `cpp` for C++. Like GitHub search, case doesn't
 * matter. Anything else, a language's display name with spaces for example, matches nothing.
 *
 * @param {URL} url The request URL.
 * @returns {Set<string>} The default aliases of the languages to leave out, for calculateLanguagePercentage.
 */
export function parseIgnoredLanguages(url) {
  const ignored = new Set();

  for (const value of url.searchParams.getAll('ignore_languages')) {
    for (const alias of value.toLowerCase().split(',')) {
      ignored.add(Object.hasOwn(LANGUAGE_ALIASES, alias) ? defaultAlias(LANGUAGE_ALIASES[alias]) : alias);
    }
  }

  return ignored;
}
